type Event struct {
	Type       string          `json:"type"`
	OccurredAt time.Time       `json:"occurred_at"`
	Data       json.RawMessage `json:"data"`   // typed payload per event type
}
data, _ := json.Marshal(OrderPlaced{OrderID: id})   // OrderPlaced{OrderID string `json:"order_id"`}
bus.Publish(Event{Type: "order.placed.v1", OccurredAt: time.Now(), Data: data})
for ev := range orders {                            // consumer: decode what it understands
	if ev.Type != "order.placed.v1" { continue }
	var p OrderPlaced
	if err := json.Unmarshal(ev.Data, &p); err == nil { onOrderPlaced(p) }
}
